arguments.query:
query Feed5Context {
  feeds(first: 80, offset: 0, orderBy: "published_at", orderDir: "desc") {
    nodes { id title status publishedAt feedBadge game { id name slug coverUrl backgroundUrl } }
    pageInfo { total first offset hasMore nextOffset }
  }
  battlefield: search(query: "Battlefield 6", first: 8) { games { id name slug status coverUrl backgroundUrl } content { id type title status publishedAt } }
  godofwar: search(query: "God of War", first: 8) { games { id name slug status coverUrl backgroundUrl } content { id type title status publishedAt } }
  gears: search(query: "Gears of War", first: 8) { games { id name slug status coverUrl backgroundUrl } content { id type title status publishedAt } }
  minecraft: search(query: "Minecraft Dungeons", first: 8) { games { id name slug status coverUrl backgroundUrl } content { id type title status publishedAt } }
  starfox: search(query: "Star Fox", first: 8) { games { id name slug status coverUrl backgroundUrl } content { id type title status publishedAt } }
  xenoblade: search(query: "Xenoblade Chronicles 3", first: 8) { games { id name slug status coverUrl backgroundUrl } content { id type title status publishedAt } }
}
